#[inline]
pub unsafe fn mz_adler32(
    mut adler: mz_ulong,
    mut ptr: *const c_uchar,
    mut buf_len: size_t,
) -> mz_ulong {
    let mut s1: mz_uint32 = (adler & 0xffff as mz_ulong) as mz_uint32;
    let mut s2: mz_uint32 = (adler >> 16 as c_int) as mz_uint32;

    if ptr.is_null() {
        return MZ_ADLER32_INIT as mz_ulong;
    }

    while buf_len != 0 {
        let block_len: size_t = if buf_len > 5552 as size_t {
            5552 as size_t
        } else {
            buf_len
        };
        let mut n = block_len;

        while n >= 8 as size_t {
            // SAFETY: `ptr` is non-null and the caller provides at least `block_len`
            // readable bytes; this loop only executes when `n >= 8`, so reading 8
            // consecutive bytes from `ptr` is within the current block.
            let p = ptr;
            s1 = s1.wrapping_add(unsafe { *p.add(0) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(1) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(2) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(3) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(4) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(5) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(6) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            s1 = s1.wrapping_add(unsafe { *p.add(7) } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            // SAFETY: advanced by 8 bytes exactly after consuming those 8 readable bytes.
            ptr = unsafe { ptr.add(8) };
            n -= 8 as size_t;
        }

        while n != 0 {
            // SAFETY: `n != 0` means one readable byte remains in the current block.
            s1 = s1.wrapping_add(unsafe { *ptr } as mz_uint32);
            s2 = s2.wrapping_add(s1);
            // SAFETY: advanced by 1 byte after consuming that readable byte.
            ptr = unsafe { ptr.add(1) };
            n -= 1;
        }

        s1 = (s1 as c_uint).wrapping_rem(65521 as c_uint) as mz_uint32;
        s2 = (s2 as c_uint).wrapping_rem(65521 as c_uint) as mz_uint32;
        buf_len = buf_len.wrapping_sub(block_len);
    }

    (s2 << 16 as c_int).wrapping_add(s1) as mz_ulong
